n = int(input())
pr = [i for i in range(n)]
a = [list(map(int, input().split())) for i in range(n)]
for e in a:
	if e[0] == 2:
		print(0)
		quit()
for i in range(n):
	for j in range(n - i):
		if a[i][j] == 1:
			for k in range(i + 1, i + j + 1):
				pr[k] = pr[k - 1]
d = [[0] * n for i in range(n)]
d[0][0] = 2
MOD = 998244353
for i in range(1, n):
	ps = 0
	for j in range(i + 1):
		if a[j][i - j] == 2:
			ps = j + 1
	for j in range(ps, i):
		d[i][j] = d[i - 1][j]
	if pr[i] >= i:
		d[i][i] = sum(d[i - 1]) % MOD
print(sum(d[n - 1]) % MOD)
